package dev.arabicgames.phone;
import org.json.*;import java.util.*;
/** Reviewed, bounded phrase rules. Does not fuzzy-match whole translations or train weights. */
final class ReviewedLanguage {
 static final class Rule {final String id,game,phrase,bad,replacement,meaning;Rule(String id,String game,String phrase,String bad,String replacement,String meaning){this.id=id;this.game=game;this.phrase=phrase;this.bad=bad;this.replacement=replacement;this.meaning=meaning;}}
 static List<Rule> parse(String json)throws Exception{JSONArray a=new JSONObject(json).optJSONArray("rules");if(a==null)return Collections.emptyList();if(a.length()>100)throw new IllegalArgumentException("Too many language rules");List<Rule> out=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject e=a.getJSONObject(i);String id=e.getString("id"),game=e.getString("game"),phrase=e.getString("source_phrase"),bad=e.getString("bad_arabic"),replacement=e.getString("replacement"),meaning=e.optString("source_meaning","");if(!e.getBoolean("reviewed")||id.isBlank()||id.length()>80||!seen.add(id)||game.isBlank()||game.length()>200||phrase.length()<4||phrase.length()>160||bad.isBlank()||bad.length()>160||replacement.isBlank()||replacement.length()>160||meaning.length()>200)throw new IllegalArgumentException("Invalid language rule");out.add(new Rule(id,game,phrase,bad,replacement,meaning));}return Collections.unmodifiableList(out);}
 static String normalize(String source){return source.toLowerCase(Locale.ROOT).replace('’','\'').replaceAll("\\s+"," ").trim();}
 static boolean containsPhrase(String source,String phrase){source=normalize(source);phrase=normalize(phrase);int at=-1;while((at=source.indexOf(phrase,at+1))>=0){int end=at+phrase.length();if((at==0||!Character.isLetterOrDigit(source.charAt(at-1)))&&(end==source.length()||!Character.isLetterOrDigit(source.charAt(end))))return true;}return false;}
 static String hints(List<Rule> rules,String game,String source){Set<String> hints=new LinkedHashSet<>();for(Rule r:rules)if(!r.meaning.isEmpty()&&(r.game.equals("*")||GameNames.same(r.game,game))&&containsPhrase(source,r.phrase)){hints.add("In this dialogue, '"+r.phrase+"' means '"+r.meaning+"'.");if(hints.size()>=3)break;}return String.join("\n",hints);}
 static String apply(List<Rule> rules,String game,String source,String arabic){for(Rule r:rules)if((r.game.equals("*")||GameNames.same(r.game,game))&&arabic.contains(r.bad)&&containsPhrase(source,r.phrase))arabic=arabic.replace(r.bad,r.replacement);return arabic;}
}
